/* Pokémon Lab — vanilla JS application layer */
const API='https://pokeapi.co/api/v2/';
const endpoints={pokemon:API+'pokemon/',species:API+'pokemon-species/',type:API+'type/',generation:API+'generation/'};
const typeColor={bug:'#26de81',dark:'#556080',dragon:'#b78cff',electric:'#fed330',fairy:'#ff4fb4',fighting:'#6b64bd',fire:'#f0932b',flying:'#72dff0',ghost:'#a55eea',grass:'#00b894',ground:'#d8a743',ice:'#74b9ff',normal:'#95afc0',poison:'#8065e8',psychic:'#c06df2',rock:'#9a7b61',steel:'#9ba9bb',water:'#0190ff'};
const TYPES=Object.keys(typeColor); const MAX_POKEMON=1025;
const KEYS={collection:'pl_collection',favorites:'pl_favorites',shiny:'pl_shiny',recent:'pl_recent',teams:'pl_teams',trainer:'pl_trainer',stats:'pl_stats',battleHistory:'pl_battle_history',mystery:'pl_mystery',daily:'pl_daily',theme:'pl_theme',settings:'pl_settings',compare:'pl_compare'};
const cache=new Map();
const state={currentPage:'home',compare:load(KEYS.compare,[]),team:[],teamName:'Untitled Team',battle:null,quiz:{mode:'silhouette',data:null,answered:false},cry:{pokemon:null,answered:false,audio:null},detail:null};

function load(k,f){try{const x=localStorage.getItem(k);return x===null?f:JSON.parse(x)}catch{return f}}
function save(k,v){localStorage.setItem(k,JSON.stringify(v))}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function cap(s=''){return s.charAt(0).toUpperCase()+s.slice(1)}
function pretty(s=''){return s.split('-').map(cap).join(' ')}
function img(p,shiny=false){return shiny?(p.sprites?.other?.['official-artwork']?.front_shiny||p.sprites?.front_shiny||official(p)):official(p)}
function official(p){return p?.sprites?.other?.['official-artwork']?.front_default||p?.sprites?.other?.dream_world?.front_default||p?.sprites?.front_default||''}
function stat(p,key){const idx={hp:0,attack:1,defense:2,'special-attack':3,'special-defense':4,speed:5}[key]??0;return p.stats?.[idx]?.base_stat??0}
function typePills(p){return (p.types||[]).map(t=>`<span style="background:${typeColor[t.type.name]||'#777'}">${esc(t.type.name)}</span>`).join('')}
function toast(message,type='success'){const host=document.getElementById('toastHost');const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;host.appendChild(el);setTimeout(()=>el.remove(),2600)}
function debounce(fn,ms=280){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}}

async function api(url){if(cache.has(url))return cache.get(url);const p=fetch(url).then(r=>{if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()});cache.set(url,p);return p}
async function getPokemon(v){const key=String(v).trim().toLowerCase();if(!key)throw new Error('empty');return api(endpoints.pokemon+encodeURIComponent(key))}
async function getSpecies(v){return api(endpoints.species+encodeURIComponent(String(v).trim().toLowerCase()))}
async function getType(v){return api(endpoints.type+encodeURIComponent(v))}
async function getMove(url){return api(url)}
function pokemonIdFromUrl(url){return Number(url.split('/').filter(Boolean).pop())}

/* Navigation */
const pageNames=['home','pokemon','type','info','collection','advanced','team','compare','typelab','calculator','battle','mystery','quiz','cryquiz','trainer','favorites','shiny','regions','analytics','settings'];
const pages=Object.fromEntries(pageNames.map(n=>[n,document.getElementById(n+'Page')]));
const menuItems=[...document.querySelectorAll('.menu-item')];
function showPage(name){if(!pages[name])return;state.currentPage=name;Object.values(pages).forEach(p=>p?.classList.remove('active'));pages[name].classList.add('active');menuItems.forEach(b=>b.classList.toggle('active',b.dataset.page===name));document.getElementById('sidebar')?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});onPageOpen(name)}
function onPageOpen(name){if(name==='home')renderHome();if(name==='collection')renderCollection();if(name==='favorites')renderFavorites();if(name==='shiny')renderShiny();if(name==='trainer')renderTrainer();if(name==='analytics')renderAnalytics();if(name==='team')renderTeam();if(name==='compare')renderCompare();if(name==='quiz')startQuiz();if(name==='cryquiz')startCryQuiz();if(name==='regions')renderRegions();if(name==='settings')loadSettingsUI();if(name==='battle')renderBattleHistory()}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page-direct]');if(p){showPage(p.dataset.pageDirect);return}const go=e.target.closest('[data-go]');if(go)showPage(go.dataset.go)});
menuItems.forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
document.getElementById('mobileMenu').onclick=()=>document.getElementById('sidebar').classList.add('open');document.getElementById('mobileClose').onclick=()=>document.getElementById('sidebar').classList.remove('open');

/* Universal search */
const globalSearch=document.getElementById('globalSearch'), suggestions=document.getElementById('globalSuggestions');
const searchCatalog=['pikachu','charizard','eevee','mewtwo','gengar','lucario','greninja','rayquaza','snorlax','bulbasaur','squirtle','cyndaquil','riolu'];
async function openGlobalSearch(v){
  globalSearch.value=''; suggestions.classList.remove('open');
  const q=String(v).trim().toLowerCase();
  if(TYPES.includes(q)){showPage('type');await searchByType(q);return}
  const gm=q.match(/^gen(?:eration)?\s*(\d)$/); if(gm){showPage('advanced');document.getElementById('advGeneration').value=gm[1];advancedSearch();return}
  if(q==='legendary'||q==='mythical'||q==='starter'||q==='fossil'||q==='paradox'){showPage('advanced');document.getElementById('advCategory').value=q;advancedSearch();return}
  showPage('pokemon'); document.getElementById('searchInput').value=v; searchPokemon();
}
globalSearch.addEventListener('input',debounce(()=>{const q=globalSearch.value.trim().toLowerCase();if(!q){suggestions.classList.remove('open');return}const hits=[...searchCatalog.filter(x=>x.includes(q)),...TYPES.filter(x=>x.includes(q))].slice(0,6);suggestions.innerHTML=hits.map(x=>`<button class="suggestion" data-global="${esc(x)}"><span>${esc(cap(x))}</span><small>${TYPES.includes(x)?'Type':'Pokémon'}</small></button>`).join('');suggestions.classList.toggle('open',hits.length>0)},120));
globalSearch.addEventListener('keydown',e=>{if(e.key==='Enter'&&globalSearch.value.trim())openGlobalSearch(globalSearch.value.trim());if(e.key==='Escape')suggestions.classList.remove('open')});
document.addEventListener('click',e=>{const s=e.target.closest('[data-global]');if(s)openGlobalSearch(s.dataset.global);else if(!e.target.closest('.global-search-wrap'))suggestions.classList.remove('open')});

/* Card component */
function isFavorite(id){return load(KEYS.favorites,[]).includes(Number(id))}
function isShiny(id){return load(KEYS.shiny,[]).includes(Number(id))}
function toggleFavorite(id){let a=load(KEYS.favorites,[]);id=Number(id);a=a.includes(id)?a.filter(x=>x!==id):[...a,id];save(KEYS.favorites,a);toast(a.includes(id)?'Added to Favorites':'Removed from Favorites');refreshAllUserViews()}
function toggleShiny(id){let a=load(KEYS.shiny,[]);id=Number(id);a=a.includes(id)?a.filter(x=>x!==id):[...a,id];save(KEYS.shiny,a);toast(a.includes(id)?'Marked as Shiny Collected':'Removed from Shiny Collection');refreshAllUserViews()}
function addCollection(p){let a=load(KEYS.collection,[]);if(a.some(x=>Number(x.id)===Number(p.id))){toast('Already in your collection','error');return false}a.push({id:p.id,name:p.name});save(KEYS.collection,a);awardXP(15);toast(`${cap(p.name)} added to Collection`);refreshAllUserViews();return true}
function removeCollection(id){save(KEYS.collection,load(KEYS.collection,[]).filter(x=>Number(x.id)!==Number(id)));toast('Removed from Collection');refreshAllUserViews()}
function rememberRecent(p){let a=load(KEYS.recent,[]).filter(x=>Number(x.id)!==Number(p.id));a.unshift({id:p.id,name:p.name});save(KEYS.recent,a.slice(0,10));let d=load(KEYS.daily,{});if(d.date===todayKey()){d.viewCount=(d.viewCount||0)+1;save(KEYS.daily,d)}}
function pokemonCard(p,{collection=false,shiny=false}={}){const fav=isFavorite(p.id), shin=isShiny(p.id);return `<article class="pokemon-card" style="--card-color:${typeColor[p.types?.[0]?.type.name]||'#2788ff'}"><button class="favorite-btn ${fav?'active':''}" title="Favorite" data-favorite="${p.id}">${fav?'♥':'♡'}</button>${collection?`<button class="shiny-toggle" data-shiny="${p.id}">${shin?'✧ Shiny Collected':'◇ Mark Shiny'}</button>`:''}<div class="card-top"><span>#${String(p.id).padStart(4,'0')}</span><b>HP ${stat(p,'hp')}</b></div><div class="card-image"><img src="${img(p,shiny)}" alt="${esc(p.name)}"></div><h3>${esc(cap(p.name))}</h3><div class="card-types">${typePills(p)}</div><div class="card-stats"><div><b>${stat(p,'attack')}</b><small>Attack</small></div><div><b>${stat(p,'defense')}</b><small>Defense</small></div><div><b>${stat(p,'speed')}</b><small>Speed</small></div></div><button class="view-detail" data-detail="${esc(p.name)}">View Details</button></article>`}

/* Pokedex search */
const searchInput=document.getElementById('searchInput'),searchBtn=document.getElementById('searchBtn'),pokemonSearchResult=document.getElementById('pokemonSearchResult');
async function searchPokemon(){
  const value=searchInput.value.trim();
  if(!value){pokemonSearchResult.innerHTML='<div class="empty-state"><div>◉</div><h2>Search the Pokédex</h2><p>Try a name or number such as Pikachu, Charizard or 25.</p></div>';return}
  pokemonSearchResult.innerHTML=`<div class="loading-panel">Researching <b>${esc(value)}</b>…</div>`;
  try{const p=await getPokemon(value);rememberRecent(p);awardXP(5);pokemonSearchResult.innerHTML=renderSearchResult(p);renderHome();}
  catch{
    try{
      const q=encodeURIComponent(value.toLowerCase()); let d=null,label='';
      try{d=await api(API+'ability/'+q);label='Ability'}catch{}
      if(!d){try{d=await api(API+'move/'+q);label='Move'}catch{}}
      if(d?.pokemon||d?.learned_by_pokemon){
        const items=d.pokemon||d.learned_by_pokemon; const ps=[];
        for(let i=0;i<Math.min(items.length,30);i+=10) ps.push(...await Promise.all(items.slice(i,i+10).map(x=>getPokemon(x.pokemon?.name||x.name))));
        pokemonSearchResult.innerHTML=`<div class="result-banner">${items.length} Pokémon associated with ${label.toLowerCase()} <b>${esc(value)}</b> · showing the first ${ps.length}.</div><div class="cards-grid">${ps.map(p=>pokemonCard(p)).join('')}</div>`;return;
      }
    }catch{}
    pokemonSearchResult.innerHTML='<div class="error-panel"><h2>Nothing found</h2><p>Try a Pokémon name, number, type, ability or move.</p><button class="secondary-btn" data-page-direct="advanced">Try Advanced Search</button></div>';
  }
}
function renderSearchResult(p){return `<div class="info-profile search-result-card"><div class="info-art-panel"><img src="${official(p)}" alt="${esc(p.name)}"></div><div class="info-main"><span class="number">#${String(p.id).padStart(4,'0')}</span><h2>${esc(cap(p.name))}</h2><div class="result-types">${typePills(p)}</div><p class="description">${esc(cap(p.name))} is a ${esc(p.types[0].type.name)}-type Pokémon. Open its full research profile for evolution, moves, abilities, forms, cries and battle information.</p><div class="info-actions"><button class="primary-btn" data-detail="${esc(p.name)}">Open Full Details</button><button class="secondary-btn" data-add="${p.id}">＋ Add to Collection</button><button class="secondary-btn" data-favorite="${p.id}">${isFavorite(p.id)?'♥ Favorited':'♡ Favorite'}</button></div><div class="bio-grid"><div><span>Height</span><b>${(p.height/10).toFixed(1)} m</b></div><div><span>Weight</span><b>${(p.weight/10).toFixed(1)} kg</b></div></div><div class="bar-list">${bar('HP',stat(p,'hp'))}${bar('Attack',stat(p,'attack'))}${bar('Defense',stat(p,'defense'))}${bar('Speed',stat(p,'speed'))}</div></div><div class="info-side"><h3>Quick Moves</h3><div class="move-list">${p.moves.slice(0,6).map(m=>`<div>${esc(pretty(m.move.name))}</div>`).join('')}</div><h3 style="margin-top:18px">Abilities</h3><div class="ability-list">${p.abilities.map(a=>`<div>${esc(pretty(a.ability.name))}</div>`).join('')}</div></div></div>`}
function bar(label,v){return `<div class="stat-bar"><span>${label}</span><div><i style="width:${Math.min(100,v/255*100)}%"></i></div><b>${v}</b></div>`}
searchBtn.onclick=searchPokemon;searchInput.onkeydown=e=>{if(e.key==='Enter')searchPokemon()};document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{searchInput.value=b.dataset.search;showPage('pokemon');searchPokemon()});

/* Type explorer */
const typeButtons=document.getElementById('typeButtons'),typeCards=document.getElementById('typeCards'),selectedType=document.getElementById('selectedType');
TYPES.forEach(t=>{const b=document.createElement('button');b.className='type-chip';b.dataset.type=t;b.innerHTML=`<span style="background:${typeColor[t]}"></span>${cap(t)}`;typeButtons.appendChild(b);b.onclick=()=>searchByType(t)});
async function searchByType(type){document.querySelectorAll('.type-chip').forEach(b=>b.classList.toggle('active',b.dataset.type===type));selectedType.textContent=`Loading all ${cap(type)} Pokémon…`;typeCards.innerHTML='<div class="loading-panel">Loading Pokémon in this type…</div>';try{const d=await getType(type);selectedType.textContent=`${d.pokemon.length} ${cap(type)} Pokémon`;typeCards.innerHTML='';for(let i=0;i<d.pokemon.length;i+=18){const batch=await Promise.all(d.pokemon.slice(i,i+18).map(x=>getPokemon(x.pokemon.name)));typeCards.insertAdjacentHTML('beforeend',batch.map(p=>pokemonCard(p)).join(''));if(i===0)typeCards.scrollIntoView({behavior:'smooth',block:'start'})}}catch{typeCards.innerHTML='<div class="error-panel"><h2>Type unavailable</h2><p>Please retry in a moment.</p></div>'}}

/* Detail + evolution profile */
const detailOverlay=document.getElementById('detailOverlay'),detailBody=document.getElementById('detailBody');
document.addEventListener('click',e=>{const d=e.target.closest('[data-detail]');if(d)openDetail(d.dataset.detail);const add=e.target.closest('[data-add]');if(add)getPokemon(add.dataset.add).then(addCollection).catch(()=>{});const fav=e.target.closest('[data-favorite]');if(fav){e.stopPropagation();toggleFavorite(fav.dataset.favorite)}});
document.getElementById('detailClose').onclick=()=>closeDetail();detailOverlay.onclick=e=>{if(e.target===detailOverlay)closeDetail()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});function closeDetail(){detailOverlay.classList.remove('open');detailOverlay.setAttribute('aria-hidden','true')}
async function openDetail(value){detailOverlay.classList.add('open');detailOverlay.setAttribute('aria-hidden','false');detailBody.innerHTML='<div class="loading-panel">Loading research profile…</div>';try{const p=await getPokemon(value);rememberRecent(p);const sp=await getSpecies(p.id);const evo=sp.evolution_chain?await api(sp.evolution_chain.url):null;const levels=[];if(evo){const walk=(n,depth=0)=>{if(!levels[depth])levels[depth]=[];levels[depth].push(pokemonIdFromUrl(n.species.url));n.evolves_to?.forEach(x=>walk(x,depth+1))};walk(evo.chain)}const ids=[...new Set(levels.flat())];const evos=await Promise.all(ids.map(id=>getPokemon(id)));const em=new Map(evos.map(x=>[x.id,x]));const desc=sp.flavor_text_entries?.find(x=>x.language.name==='en')?.flavor_text?.replace(/[\n\f]/g,' ')||'No English Pokédex description is available.';const weaknesses=await weaknessesForPokemon(p);const forms=[p,...(p.forms||[]).filter(f=>f.name!==p.name)];detailBody.innerHTML=`<div class="detail-wrap"><div class="detail-visual"><img src="${official(p)}" alt="${esc(p.name)}"></div><div class="detail-content"><span class="number">#${String(p.id).padStart(4,'0')} • ${esc(pretty(sp.generation?.name||''))}</span><h2>${esc(cap(p.name))}</h2><div class="result-types">${typePills(p)}</div><div class="detail-actions"><button class="primary-btn" data-add="${p.id}">＋ Add to Collection</button><button class="secondary-btn" data-favorite="${p.id}">${isFavorite(p.id)?'♥ Favorited':'♡ Favorite'}</button><button class="secondary-btn" data-compare-add="${p.id}">⇄ Compare</button><button class="secondary-btn" data-battle-add="${p.name}">⚔ Battle</button><button class="cry-btn" data-play-cry="${p.id}">♫ Play Cry</button></div><div class="detail-section"><h3>Overview</h3><p class="description">${esc(desc)}</p><div class="bio-grid"><div><span>Height</span><b>${(p.height/10).toFixed(1)} m</b></div><div><span>Weight</span><b>${(p.weight/10).toFixed(1)} kg</b></div><div><span>Abilities</span><b>${p.abilities.length}</b></div><div><span>Forms</span><b>${forms.length}</b></div></div></div><div class="detail-section"><h3>Base Stats</h3><div class="bar-list">${bar('HP',stat(p,'hp'))}${bar('Attack',stat(p,'attack'))}${bar('Defense',stat(p,'defense'))}${bar('Sp. Atk',stat(p,'special-attack'))}${bar('Sp. Def',stat(p,'special-defense'))}${bar('Speed',stat(p,'speed'))}</div></div><div class="detail-section"><h3>Weaknesses & Resistances</h3><div class="weakness-grid">${weaknesses.map(x=>`<span style="background:${x.mult>1?'#5a2738':x.mult===0?'#3b3b4e':'#164b3c'}">${cap(x.type)} ×${x.mult}</span>`).join('')}</div></div><div class="detail-section"><h3>Evolution Chain</h3><div class="evolution-tree">${levels.flatMap((lev,i)=>[...lev.map(id=>{const q=em.get(id);return `<button class="evo-node" data-detail="${q?.name}"><img src="${official(q)}" alt="${q?.name}"><b>${cap(q?.name||'')}</b></button>`}),i<levels.length-1?'<span class="evo-arrow">→</span>':'']).join('')}</div></div></div><aside class="info-side"><h3>Abilities</h3><div class="ability-list">${p.abilities.map(a=>`<div>${esc(pretty(a.ability.name))}${a.is_hidden?' <small>Hidden</small>':''}</div>`).join('')}</div><h3 style="margin-top:18px">Moves</h3><div class="move-list">${p.moves.slice(0,16).map(m=>`<div>${esc(pretty(m.move.name))}</div>`).join('')}</div><h3 style="margin-top:18px">Forms</h3><div class="form-grid">${forms.map(f=>`<div><img src="${official(p)}" alt="${f.name}"><small>${cap(f.name)}</small></div>`).join('')}</div></aside></div>`}catch(err){console.error(err);detailBody.innerHTML='<div class="error-panel"><h2>Research profile unavailable</h2><p>Some Pokémon data could not be loaded. Please retry.</p></div>'}}
async function weaknessesForPokemon(p){const rel=await Promise.all(p.types.map(t=>getType(t.type.name)));return TYPES.map(t=>{let mult=1;for(const d of rel){if(d.damage_relations.double_damage_from.some(x=>x.name===t))mult*=2;if(d.damage_relations.half_damage_from.some(x=>x.name===t))mult*=.5;if(d.damage_relations.no_damage_from.some(x=>x.name===t))mult*=0}return{type:t,mult}}).filter(x=>x.mult!==1).sort((a,b)=>b.mult-a.mult)}

/* Info page */
const infoSearchInput=document.getElementById('infoSearchInput'),infoSearchBtn=document.getElementById('infoSearchBtn'),infoResult=document.getElementById('infoResult');
async function searchInfo(){const v=infoSearchInput.value.trim();if(!v)return;infoResult.innerHTML='<div class="loading-panel">Building evolution tree…</div>';try{const p=await getPokemon(v);const sp=await getSpecies(p.id);const chain=sp.evolution_chain?await api(sp.evolution_chain.url):null;const levels=[];if(chain){const walk=(n,d=0)=>{if(!levels[d])levels[d]=[];levels[d].push(pokemonIdFromUrl(n.species.url));n.evolves_to?.forEach(x=>walk(x,d+1))};walk(chain.chain)}else levels.push([p.id]);const ids=[...new Set(levels.flat())],ps=await Promise.all(ids.map(getPokemon)),map=new Map(ps.map(x=>[x.id,x]));rememberRecent(p);awardXP(10);infoResult.innerHTML=`<div class="info-profile"><div class="info-art-panel"><img src="${official(p)}" alt="${esc(p.name)}"></div><div class="info-main"><span class="number">EVOLUTION FAMILY • ${ids.length} SPECIES</span><h2>${esc(cap(p.name))}</h2><div class="result-types">${typePills(p)}</div><div class="info-actions"><button class="primary-btn" data-detail="${p.name}">Open Full Research</button><button class="secondary-btn" data-add="${p.id}">＋ Collection</button></div><div class="detail-section"><h3>Evolution Tree</h3><div class="evolution-tree">${levels.map((lev,i)=>`${lev.map(id=>{const q=map.get(id);return `<button class="evo-node" data-info-node="${q.name}"><img src="${official(q)}" alt="${q.name}"><b>${cap(q.name)}</b><small>#${String(q.id).padStart(4,'0')}</small></button>`}).join(i<levels.length-1?'<span class="evo-arrow">→</span>':'')}`).join('<span class="evo-arrow">→</span>')}</div></div><div class="detail-section"><h3>Stats</h3><div class="bar-list">${bar('HP',stat(p,'hp'))}${bar('Attack',stat(p,'attack'))}${bar('Defense',stat(p,'defense'))}${bar('Speed',stat(p,'speed'))}</div></div></div><aside class="info-side"><h3>Family Stages</h3><div class="ability-list">${levels.map((lev,i)=>`<div>Stage ${i+1}: ${lev.map(id=>cap(map.get(id)?.name||'')).join(', ')}</div>`).join('')}</div><h3 style="margin-top:18px">Research Notes</h3><p class="description">Evolution families are sourced from PokéAPI. Branching families are shown as multiple Pokémon within the same stage.</p></aside></div>`}catch{infoResult.innerHTML='<div class="error-panel"><h2>Pokémon not found</h2><p>Try Pikachu, Eevee or a valid Pokédex number.</p></div>'}}
infoSearchBtn.onclick=searchInfo;infoSearchInput.onkeydown=e=>{if(e.key==='Enter')searchInfo()};document.querySelectorAll('[data-info-search]').forEach(b=>b.onclick=()=>{showPage('info');infoSearchInput.value=b.dataset.infoSearch;searchInfo()});document.addEventListener('click',e=>{const n=e.target.closest('[data-info-node]');if(n){infoSearchInput.value=n.dataset.infoNode;searchInfo()}});

/* Collection */
const collectionCards=document.getElementById('collectionCards'),collectionSearchInput=document.getElementById('collectionSearchInput'),collectionSearchResult=document.getElementById('collectionSearchResult');
async function renderCollection(){
  const list=load(KEYS.collection,[]), favs=load(KEYS.favorites,[]), shin=load(KEYS.shiny,[]);
  document.getElementById('collectionCount').textContent=`${list.length} / ${MAX_POKEMON}`;
  document.getElementById('collectionSummaryCount').textContent=list.length;
  document.getElementById('favoriteSummaryCount').textContent=favs.length;
  document.getElementById('shinySummaryCount').textContent=shin.length;
  const pct=Math.round(list.length/MAX_POKEMON*100); document.getElementById('collectionProgressBar').style.width=pct+'%';
  const filter=document.getElementById('collectionFilter').value, sort=document.getElementById('collectionSort').value;
  const typeFilter=document.getElementById('collectionTypeFilter').value, genFilter=document.getElementById('collectionGenerationFilter').value;
  let ids=list.map(x=>Number(x.id));
  if(filter==='missing') ids=Array.from({length:Math.min(MAX_POKEMON,60)},(_,i)=>i+1).filter(id=>!list.some(x=>Number(x.id)===id));
  if(filter==='favorites') ids=ids.filter(id=>favs.includes(Number(id)));
  if(filter==='shiny') ids=ids.filter(id=>shin.includes(Number(id)));
  if(genFilter!=='all') ids=ids.filter(id=>id>=genRanges[genFilter][0]&&id<=genRanges[genFilter][1]);
  let ps=[]; for(let i=0;i<ids.length;i+=20) ps.push(...await Promise.all(ids.slice(i,i+20).map(id=>getPokemon(id).catch(()=>null)))); ps=ps.filter(Boolean);
  if(typeFilter!=='all') ps=ps.filter(p=>p.types.some(t=>t.type.name===typeFilter));
  if(filter==='legendary'||filter==='mythical'){const specs=await Promise.all(ps.map(p=>getSpecies(p.id).catch(()=>null)));ps=ps.filter((p,i)=>filter==='legendary'?!!specs[i]?.is_legendary:!!specs[i]?.is_mythical)}
  if(sort==='name')ps.sort((a,b)=>a.name.localeCompare(b.name)); if(sort==='type')ps.sort((a,b)=>a.types[0].type.name.localeCompare(b.types[0].type.name));
  if(!ps.length){collectionCards.innerHTML='<div class="empty-state"><div>▥</div><h2>No Pokémon match these filters</h2><p>Try another filter or add more Pokémon to your collection.</p><button class="primary-btn" data-page-direct="pokemon">Explore Pokédex</button></div>';return}
  collectionCards.innerHTML=ps.map(p=>pokemonCard(p,{collection:true,shiny:filter==='shiny'||isShiny(p.id)})).join(''); renderHomeProgress();
}
document.getElementById('collectionSearchBtn').onclick=searchCollection;collectionSearchInput.onkeydown=e=>{if(e.key==='Enter')searchCollection()};async function searchCollection(){const v=collectionSearchInput.value.trim();if(!v)return;collectionSearchResult.innerHTML='<div class="loading-panel">Searching…</div>';try{const p=await getPokemon(v);collectionSearchResult.innerHTML=`<div class="panel" style="padding:12px;margin-bottom:12px;display:flex;align-items:center;gap:12px"><img src="${official(p)}" style="width:80px;height:80px;object-fit:contain"><div style="flex:1"><b>${esc(cap(p.name))}</b><p class="description">#${p.id} · ${esc(p.types.map(x=>x.type.name).join(' / '))}</p></div><button class="primary-btn" data-add="${p.id}">${load(KEYS.collection,[]).some(x=>Number(x.id)===p.id)?'✓ In Collection':'＋ Add'}</button><button class="secondary-btn" data-detail="${p.name}">Info</button></div>`}catch{collectionSearchResult.innerHTML='<div class="error-panel"><h2>Pokémon not found</h2></div>'}}
