const advType=document.getElementById('advType');TYPES.forEach(t=>advType.insertAdjacentHTML('beforeend',`<option value="${t}">${cap(t)}</option>`));
const collectionTypeFilter=document.getElementById('collectionTypeFilter');TYPES.forEach(t=>collectionTypeFilter.insertAdjacentHTML('beforeend',`<option value="${t}">${cap(t)}</option>`));collectionTypeFilter.onchange=renderCollection;document.getElementById('collectionGenerationFilter').onchange=renderCollection;
let speciesCatalog=null;async function getSpeciesCatalog(){if(speciesCatalog)return speciesCatalog;const d=await api(endpoints.species+'?limit=1300');speciesCatalog=d.results.map(x=>({name:x.name,id:pokemonIdFromUrl(x.url)}));return speciesCatalog}
const genRanges={1:[1,151],2:[152,251],3:[252,386],4:[387,493],5:[494,649],6:[650,721],7:[722,809],8:[810,905],9:[906,1025]};
const starters=new Set(['bulbasaur','ivysaur','venusaur','charmander','charmeleon','charizard','squirtle','wartortle','blastoise','chikorita','bayleef','meganium','cyndaquil','quilava','typhlosion','totodile','croconaw','feraligatr','treecko','grovyle','sceptile','torchic','combusken','blaziken','mudkip','marshtomp','swampert','turtwig','grotle','torterra','chimchar','monferno','infernape','piplup','prinplup','empoleon','snivy','servine','serperior','tepig','pignite','emboar','oshawott','dewott','samurott','chespin','quilladin','chesnaught','fennekin','braixen','delphox','froakie','frogadier','greninja','rowlet','dartrix','decidueye','litten','torracat','incineroar','grookey','thwackey','rillaboom','scorbunny','raboot','cinderace','sobble','drizzile','inteleon','sprigatito','floragato','meowscarada','fuecoco','crocalor','skeledirge','quaxly','quaxwell','quaquaval']);
const fossils=new Set(['omanyte','omastar','kabuto','kabutops','aerodactyl','lileep','cradily','anorith','armaldo','shieldon','bastiodon','cranidos','rampardos','tirtouga','carracosta','archen','archeops','tyrunt','tyrantrum','amaura','aurorus','dracozolt','arctozolt','dracovish','arctovish']);
const paradox=new Set(['great-tusk','scream-tail','brute-bonnet','flutter-mane','slither-wing','sandy-shocks','roaring-moon','walking-wake','gouging-fire','raging-bolt','iron-treads','iron-bundle','iron-hands','iron-jugulis','iron-moth','iron-thorns','iron-valiant','iron-leaves','iron-boulder','iron-crown']);
async function advancedSearch(){const status=document.getElementById('advancedStatus'),root=document.getElementById('advancedCards');status.textContent='Preparing search…';root.innerHTML='<div class="loading-panel">Filtering the Pokédex…</div>';try{let cat=await getSpeciesCatalog();const gen=document.getElementById('advGeneration').value,type=document.getElementById('advType').value,category=document.getElementById('advCategory').value,statKey=document.getElementById('advStat').value,cond=document.getElementById('advCondition').value,val=Number(document.getElementById('advValue').value||0);if(gen!=='all')cat=cat.filter(x=>x.id>=genRanges[gen][0]&&x.id<=genRanges[gen][1]);if(category!=='all')cat=cat.filter(x=>category==='starter'?starters.has(x.name):category==='fossil'?fossils.has(x.name):category==='paradox'?paradox.has(x.name):true);let candidates=cat;if(type!=='all'){const td=await getType(type);const ids=new Set(td.pokemon.map(x=>pokemonIdFromUrl(x.pokemon.url)));candidates=candidates.filter(x=>ids.has(x.id))}let ps=[];const sample=candidates.slice(0,80);for(let i=0;i<sample.length;i+=20)ps.push(...await Promise.all(sample.slice(i,i+20).map(x=>getPokemon(x.id))));if(category==='legendary'||category==='mythical'){const ss=await Promise.all(ps.map(p=>getSpecies(p.id)));ps=ps.filter((p,i)=>category==='legendary'?ss[i]?.is_legendary:ss[i]?.is_mythical)}if(statKey!=='none'){ps=ps.filter(p=>{const n=stat(p,statKey);return cond==='gt'?n>val:cond==='gte'?n>=val:cond==='lt'?n<val:n<=val})}status.textContent=`${ps.length} result${ps.length===1?'':'s'} shown${candidates.length>80?' · showing the first 80 candidates for performance':''}`;root.innerHTML=ps.length?ps.map(p=>pokemonCard(p)).join(''):'<div class="empty-state"><div>⌘</div><h2>No matches</h2><p>Try relaxing one or more filters.</p></div>'}catch(e){console.error(e);root.innerHTML='<div class="error-panel"><h2>Advanced search failed</h2><p>Please retry.</p></div>'}}
document.getElementById('advancedApply').onclick=advancedSearch;document.getElementById('advancedReset').onclick=()=>{['advGeneration','advType','advCategory','advStat','advCondition'].forEach(id=>document.getElementById(id).selectedIndex=0);document.getElementById('advValue').value='';document.getElementById('advancedStatus').textContent='Set filters and run a search.';document.getElementById('advancedCards').innerHTML=''};

