const compareSearchInput=document.getElementById('compareSearchInput');document.getElementById('compareAddBtn').onclick=async()=>{const v=compareSearchInput.value.trim();if(!v)return;try{const p=await getPokemon(v);if(state.compare.includes(p.id)){toast('Already added to Compare','error');return}if(state.compare.length>=4){toast('Compare supports up to 4 Pokémon','error');return}state.compare.push(p.id);save(KEYS.compare,state.compare);compareSearchInput.value='';renderCompare();toast(`${cap(p.name)} added to Compare`)}catch{toast('Pokémon not found','error')}};
async function renderCompare(){const root=document.getElementById('compareContent');if(!state.compare.length){root.innerHTML='<div class="empty-state"><div>⇄</div><h2>Build a comparison</h2><p>Add 2–4 Pokémon using the search above.</p></div>';return}const ps=await Promise.all(state.compare.map(getPokemon));root.innerHTML=`<div class="panel" style="padding:15px"><div class="compare-chips">${ps.map(p=>`<span class="compare-chip">${cap(p.name)} <button data-compare-remove="${p.id}">×</button></span>`).join('')}</div></div><div class="compare-table-wrap"><table class="compare-table"><tr><th>Metric</th>${ps.map(p=>`<th><img src="${official(p)}" alt="${p.name}"><br>${cap(p.name)}<div class="result-types" style="justify-content:center">${typePills(p)}</div></th>`).join('')}</tr>${['hp','attack','defense','special-attack','special-defense','speed'].map(k=>`<tr><td>${pretty(k)}</td>${ps.map(p=>`<td><div class="compare-stat"><b>${stat(p,k)}</b><div><i style="width:${Math.min(100,stat(p,k)/255*100)}%"></i></div></div></td>`).join('')}</tr>`).join('')}<tr><td>Height</td>${ps.map(p=>`<td>${(p.height/10).toFixed(1)} m</td>`).join('')}</tr><tr><td>Weight</td>${ps.map(p=>`<td>${(p.weight/10).toFixed(1)} kg</td>`).join('')}</tr><tr><td>Abilities</td>${ps.map(p=>`<td>${p.abilities.map(a=>pretty(a.ability.name)).join(', ')}</td>`).join('')}</tr></table></div>`}
document.addEventListener('click',e=>{const r=e.target.closest('[data-compare-remove]');if(r){state.compare=state.compare.filter(x=>x!==Number(r.dataset.compareRemove));save(KEYS.compare,state.compare);renderCompare()}const c=e.target.closest('[data-compare-add]');if(c){const id=Number(c.dataset.compareAdd);if(!state.compare.includes(id)&&state.compare.length<4){state.compare.push(id);save(KEYS.compare,state.compare);toast('Added to Compare');renderCompare()}}});

/* Type lab */
function fillTypeSelect(id,none=false){const el=document.getElementById(id);if(!el)return;if(none)el.innerHTML='<option value="none">None</option>';TYPES.forEach(t=>el.insertAdjacentHTML('beforeend',`<option value="${t}">${cap(t)}</option>`))}fillTypeSelect('attackType');fillTypeSelect('defendType1');fillTypeSelect('defendType2',true);
async function calculateType(){const a=document.getElementById('attackType').value,d1=document.getElementById('defendType1').value,d2=document.getElementById('defendType2').value;const root=document.getElementById('typeResult');if(!a||!d1){root.innerHTML='<div class="empty-state compact"><h3>Select defending types</h3></div>';return}try{const [r1,r2]=await Promise.all([getType(d1),d2!=='none'?getType(d2):Promise.resolve(null)]);let mult=1;for(const r of [r1,r2].filter(Boolean)){if(r.damage_relations.double_damage_from.some(x=>x.name===a))mult*=2;if(r.damage_relations.half_damage_from.some(x=>x.name===a))mult*=.5;if(r.damage_relations.no_damage_from.some(x=>x.name===a))mult=0}let label=mult===0?'Immune':mult>1?'Super effective':mult<1?'Not very effective':'Neutral';root.innerHTML=`<div class="effect-result"><div class="multiplier">×${mult}</div><div class="effect-label">${label}</div><div class="effect-badges"><span style="background:${typeColor[a]}">${cap(a)}</span><span>→</span><span style="background:${typeColor[d1]}">${cap(d1)}</span>${d2!=='none'?`<span style="background:${typeColor[d2]}">${cap(d2)}</span>`:''}</div><p class="description">The multiplier is derived from PokéAPI type damage relations and is shown without assuming a particular battle generation.</p></div>`}catch{root.innerHTML='<div class="error-panel"><h2>Type data unavailable</h2></div>'}}
document.getElementById('calculateType').onclick=calculateType;
function renderMatrix(){const root=document.getElementById('typeMatrix');root.innerHTML=`<table><tr><th>ATK ↓ / DEF →</th>${TYPES.map(t=>`<th>${cap(t).slice(0,3)}</th>`).join('')}</tr>${TYPES.map(a=>`<tr><th style="background:${typeColor[a]}33">${cap(a)}</th>${TYPES.map(d=>`<td class="matrix-cell" data-a="${a}" data-d="${d}">·</td>`).join('')}</tr>`).join('')}</table>`;TYPES.forEach(async a=>{const rel=await getType(a);TYPES.forEach(d=>{let m=1;if(rel.damage_relations.double_damage_to.some(x=>x.name===d))m=2;if(rel.damage_relations.half_damage_to.some(x=>x.name===d))m=.5;if(rel.damage_relations.no_damage_to.some(x=>x.name===d))m=0;const c=root.querySelector(`[data-a="${a}"][data-d="${d}"]`);if(c){c.textContent=m===2?'×2':m===.5?'×½':m===0?'×0':'·';c.className=`matrix-cell ${m===2?'matrix-super':m===.5?'matrix-weak':m===0?'matrix-immune':'matrix-neutral'}`}})})}renderMatrix();

