async function loadStatPokemon(){try{const p=await getPokemon(document.getElementById('statPokemon').value);['hp','attack','defense','special-attack','special-defense','speed'].forEach((k,i)=>document.getElementById(['baseHP','baseAtk','baseDef','baseSpA','baseSpD','baseSpeed'][i]).value=stat(p,k));toast(`${cap(p.name)} base stats loaded`)}catch{toast('Pokémon not found','error')}}
document.getElementById('loadStatPokemon').onclick=loadStatPokemon;document.getElementById('calculateStats').onclick=()=>{const lvl=Number(document.getElementById('statLevel').value||50),bases=[['HP','baseHP'],['Attack','baseAtk'],['Defense','baseDef'],['Sp. Attack','baseSpA'],['Sp. Defense','baseSpD'],['Speed','baseSpeed']];const out=bases.map(([n,id])=>{const b=Number(document.getElementById(id).value||0);const value=n==='HP'?Math.floor(((2*b+31)*lvl)/100)+lvl+10:Math.floor(((2*b+31)*lvl)/100)+5;return [n,value]});document.getElementById('statOutput').innerHTML=`<div class="calc-output"><h3>Estimated Level ${lvl} Stats</h3><div class="bar-list">${out.map(x=>bar(x[0],x[1])).join('')}</div><p class="description">Simplified base-stat estimate; EVs, IVs, nature and other game-specific mechanics are not included.</p></div>`};
document.getElementById('calculateDamage').onclick=async()=>{const a=document.getElementById('damageAttacker').value.trim(),d=document.getElementById('damageDefender').value.trim(),type=document.getElementById('damageType').value,lvl=Number(document.getElementById('damageLevel').value||50),power=Number(document.getElementById('damagePower').value||80),mod=Number(document.getElementById('damageModifier').value||1),out=document.getElementById('damageOutput');if(!a||!d){out.innerHTML='<div class="error-panel"><h2>Enter attacker and defender</h2></div>';return}out.innerHTML='<div class="loading-panel">Calculating estimate…</div>';try{const [pa,pd]=await Promise.all([getPokemon(a),getPokemon(d)]);const rel=await getType(pd.types[0].type.name);let eff=1;if(rel.damage_relations.double_damage_from.some(x=>x.name===type))eff*=2;if(rel.damage_relations.half_damage_from.some(x=>x.name===type))eff*=.5;if(rel.damage_relations.no_damage_from.some(x=>x.name===type))eff=0;const raw=Math.floor((((2*lvl/5+2)*power*stat(pa,'attack')/Math.max(1,stat(pd,'defense')))/50)+2);const stab=pa.types.some(x=>x.type.name===type)?1.5:1;const damage=Math.floor(raw*stab*eff*mod);const pct=Math.min(100,damage/Math.max(1,stat(pd,'hp'))*100);out.innerHTML=`<div class="calc-output"><h3>Estimated Damage: ${damage}</h3><div class="big-progress"><i style="width:${pct}%"></i></div><p class="description">About ${pct.toFixed(1)}% of ${cap(pd.name)}'s base HP. Type multiplier ×${eff}; STAB ${stab}×. This is a simplified estimate, not official battle mechanics.</p></div>`}catch{out.innerHTML='<div class="error-panel"><h2>Could not calculate</h2><p>Check both Pokémon names.</p></div>'}};
document.querySelectorAll('.calc-tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.calc-tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.calc-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.calc==='stat'?'statCalc':b.dataset.calc==='damage'?'damageCalc':'weaknessCalc').classList.add('active')});
document.getElementById('findWeakness').onclick=async()=>{const v=document.getElementById('weaknessPokemon').value.trim(),out=document.getElementById('weaknessOutput');if(!v)return;out.innerHTML='<div class="loading-panel">Analyzing…</div>';try{const p=await getPokemon(v),w=await weaknessesForPokemon(p);out.innerHTML=`<div class="calc-output"><h3>${cap(p.name)} Type Profile</h3><p class="description">${p.types.map(x=>cap(x.type.name)).join(' / ')}</p><div class="weakness-grid">${w.map(x=>`<span style="background:${x.mult>1?'#5a2738':x.mult===0?'#3b3b4e':'#164b3c'}">${cap(x.type)} ×${x.mult}</span>`).join('')}</div></div>`}catch{out.innerHTML='<div class="error-panel"><h2>Pokémon not found</h2></div>'}};

/* Team builder */
const teamSearchInput=document.getElementById('teamSearchInput');document.getElementById('teamSearchBtn').onclick=async()=>{const v=teamSearchInput.value.trim();if(!v)return;try{const p=await getPokemon(v);if(state.team.some(x=>x.id===p.id)){toast('Already on team','error');return}if(state.team.length>=6){toast('A team can contain up to 6 Pokémon','error');return}state.team.push({id:p.id,name:p.name});teamSearchInput.value='';renderTeam();awardXP(8)}catch{toast('Pokémon not found','error')}};teamSearchInput.onkeydown=e=>{if(e.key==='Enter')document.getElementById('teamSearchBtn').click()};
async function renderTeam(){const root=document.getElementById('teamSlots');document.getElementById('activeTeamTitle').textContent=state.teamName;const ps=await Promise.all(state.team.map(x=>getPokemon(x.id)));root.innerHTML=[...ps.map((p,i)=>`<div class="team-slot filled"><div style="position:absolute;left:7px;top:7px;display:flex;gap:3px"><button class="secondary-btn" data-team-up="${p.id}" style="padding:4px 6px">↑</button><button class="secondary-btn" data-team-down="${p.id}" style="padding:4px 6px">↓</button></div><button class="danger-btn" data-team-remove="${p.id}">×</button><img src="${official(p)}" alt="${p.name}"><h4>${cap(p.name)}</h4><div class="result-types">${typePills(p)}</div></div>`),...Array(6-ps.length).fill(0).map(()=>'<div class="team-slot"><span class="team-empty">Empty Slot<br>Search a Pokémon above</span></div>')].join('');renderTeamAnalysis(ps);renderSavedTeams()}
async function renderTeamAnalysis(ps){
  const root=document.getElementById('teamAnalysis');
  if(!ps.length){root.innerHTML='<p class="description">Add Pokémon to see defensive coverage.</p>';return}
  const weak=new Map();
  for(const p of ps){const ws=await weaknessesForPokemon(p);ws.filter(x=>x.mult>1).forEach(x=>weak.set(x.type,(weak.get(x.type)||0)+1))}
  const strong=[...new Set(ps.flatMap(p=>p.types.map(t=>t.type.name)))];
  const repeated=[...weak.entries()].sort((a,b)=>b[1]-a[1]).slice(0,3);
  let rec=[];
  for(const [t] of repeated){try{const td=await getType(t);const picks=td.pokemon.slice(0,2);rec.push(...picks.map(x=>x.pokemon.name))}catch{}}
  root.innerHTML=`<div class="coverage-group"><h4>Team Types</h4><div class="coverage-tags">${strong.map(t=>`<span style="background:${typeColor[t]}">${cap(t)}</span>`).join('')}</div></div><div class="coverage-group"><h4>Repeated Weaknesses</h4><div class="coverage-tags">${repeated.map(([t,n])=>`<span style="background:#5a2738">${cap(t)} ×${n}</span>`).join('')||'<span style="background:#164b3c">No repeated weaknesses</span>'}</div></div><div class="coverage-group"><h4>Coverage Suggestions</h4><div class="coverage-tags">${[...new Set(rec)].slice(0,6).map(n=>`<button class="secondary-btn" data-team-suggest="${n}">${cap(n)}</button>`).join('')||'<span style="background:#17385d">No suggestion yet</span>'}</div></div><p class="description">Suggestions are drawn from Pokémon returned by the type endpoint for repeated team weaknesses.</p>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-team-suggest]');if(b){teamSearchInput.value=b.dataset.teamSuggest;document.getElementById('teamSearchBtn').click()}});document.getElementById('teamName').oninput=e=>state.teamName=e.target.value||'Untitled Team';document.getElementById('clearTeam').onclick=()=>{state.team=[];renderTeam()};document.addEventListener('click',e=>{const r=e.target.closest('[data-team-remove]');if(r){state.team=state.team.filter(x=>x.id!==Number(r.dataset.teamRemove));renderTeam()}});
document.addEventListener('click',e=>{const up=e.target.closest('[data-team-up]');const down=e.target.closest('[data-team-down]');if(up||down){const id=Number((up||down).dataset.teamUp||down.dataset.teamDown),i=state.team.findIndex(x=>x.id===id),j=up?i-1:i+1;if(i>=0&&j>=0&&j<state.team.length){[state.team[i],state.team[j]]=[state.team[j],state.team[i]];renderTeam()}}});document.getElementById('saveTeam').onclick=()=>{if(!state.team.length){toast('Add Pokémon first','error');return}const teams=load(KEYS.teams,[]);const item={id:Date.now(),name:state.teamName||'Untitled Team',pokemon:state.team};teams.push(item);save(KEYS.teams,teams);toast('Team saved');renderSavedTeams()};function renderSavedTeams(){const root=document.getElementById('savedTeams'),teams=load(KEYS.teams,[]);root.innerHTML=teams.length?teams.map(t=>`<div class="saved-team"><div><strong>${esc(t.name)}</strong><small>${t.pokemon.length} Pokémon</small></div><div><button class="secondary-btn" data-load-team="${t.id}">Load</button><button class="danger-btn" data-delete-team="${t.id}">Delete</button></div></div>`).join(''):'<p class="description">No saved teams yet.</p>'}document.addEventListener('click',e=>{const l=e.target.closest('[data-load-team]');if(l){const t=load(KEYS.teams,[]).find(x=>x.id===Number(l.dataset.loadTeam));if(t){state.team=t.pokemon;state.teamName=t.name;document.getElementById('teamName').value=t.name;renderTeam()}}const d=e.target.closest('[data-delete-team]');if(d){save(KEYS.teams,load(KEYS.teams,[]).filter(x=>x.id!==Number(d.dataset.deleteTeam)));renderSavedTeams()}});

/* Battle simulator */
const battleState={};
document.getElementById('battleBtn').onclick=prepareBattle;document.getElementById('resetBattle').onclick=()=>{Object.keys(battleState).forEach(k=>delete battleState[k]);document.getElementById('battleArena').innerHTML='';document.getElementById('battleControls').innerHTML=''};
async function prepareBattle(){const a=document.getElementById('battleOne').value.trim(),b=document.getElementById('battleTwo').value.trim(),arena=document.getElementById('battleArena');if(!a||!b){arena.innerHTML='<div class="battle-empty">Enter both Pokémon to prepare a battle.</div>';return}arena.innerHTML='<div class="loading-panel">Preparing battle…</div>';try{const [p1,p2]=await Promise.all([getPokemon(a),getPokemon(b)]);battleState.p1={p:p1,hp:stat(p1,'hp')};battleState.p2={p:p2,hp:stat(p2,'hp')};battleState.turn=stat(p1,'speed')>=stat(p2,'speed')?1:2;battleState.log=[];const moves1=await Promise.all(p1.moves.slice(0,3).map(m=>getMove(m.move.url)));const moves2=await Promise.all(p2.moves.slice(0,3).map(m=>getMove(m.move.url)));battleState.moves1=moves1.filter(m=>m.type).slice(0,3);battleState.moves2=moves2.filter(m=>m.type).slice(0,3);renderBattle();awardXP(5)}catch{arena.innerHTML='<div class="error-panel"><h2>Battle Pokémon not found</h2><p>Check both search fields.</p></div>'}}
function renderBattle(){const s1=battleState.p1,s2=battleState.p2;document.getElementById('battleArena').innerHTML=battleCardHTML(s1,'YOUR POKÉMON','blue')+'<div class="versus">VS<div>⚡</div></div>'+battleCardHTML(s2,'OPPONENT','red');const active=battleState.turn===1?s1:s2;const moves=battleState.turn===1?battleState.moves1:battleState.moves2;document.getElementById('battleControls').innerHTML=battleState.winner?`<button class="primary-btn" onclick="prepareBattle()">Battle Again</button>`:`<div class="panel" style="padding:10px;text-align:center;width:100%"><p class="description">${cap(active.p.name)}'s turn</p>${moves.map(m=>`<button class="secondary-btn" data-battle-move="${esc(m.name)}">${pretty(m.name)} · ${cap(m.type.name)}</button>`).join('')}</div>`;document.querySelectorAll('[data-battle-move]').forEach(b=>b.onclick=()=>battleMove(b.dataset.battleMove))}
function battleCardHTML(s,label,side){const pct=Math.max(0,s.hp)/Math.max(1,stat(s.p,'hp'))*100;return `<article class="battle-card ${side}"><h2>${label}</h2><div class="battle-art"><img src="${official(s.p)}" alt="${s.p.name}"></div><h3>${cap(s.p.name)}</h3><div class="battle-type">${typePills(s.p)}</div><div class="hp-line"><span>HP</span><b>${Math.max(0,s.hp)} / ${stat(s.p,'hp')}</b><div class="hp-track"><i style="width:${pct}%"></i></div></div><div class="battle-stats-list"><div><span>Attack</span><b>${stat(s.p,'attack')}</b></div><div><span>Defense</span><b>${stat(s.p,'defense')}</b></div><div><span>Speed</span><b>${stat(s.p,'speed')}</b></div></div></article>`}
async function battleMove(moveName){if(battleState.winner)return;const attacker=battleState.turn===1?battleState.p1:battleState.p2,defender=battleState.turn===1?battleState.p2:battleState.p1;const move=(battleState.turn===1?battleState.moves1:battleState.moves2).find(m=>m.name===moveName);if(!move)return;const rels=await Promise.all(defender.p.types.map(t=>getType(t.type.name)));let eff=1;for(const r of rels){if(r.damage_relations.double_damage_from.some(x=>x.name===move.type.name))eff*=2;if(r.damage_relations.half_damage_from.some(x=>x.name===move.type.name))eff*=.5;if(r.damage_relations.no_damage_from.some(x=>x.name===move.type.name))eff=0}const power=move.power||50;const raw=Math.floor((((2*50/5+2)*power*stat(attacker.p,'attack')/Math.max(1,stat(defender.p,'defense')))/50)+2);const stab=attacker.p.types.some(t=>t.type.name===move.type.name)?1.5:1;const dmg=Math.max(eff===0?0:1,Math.floor(raw*eff*stab));defender.hp=Math.max(0,defender.hp-dmg);battleState.log.unshift(`${cap(attacker.p.name)} used ${pretty(move.name)} for ${dmg} damage (×${eff} effectiveness).`);if(defender.hp<=0){battleState.winner=attacker.p.name;battleState.log.unshift(`${cap(attacker.p.name)} wins the battle!`);awardBattle(true)}else battleState.turn=battleState.turn===1?2:1;renderBattle();document.getElementById('battleLog').innerHTML=battleState.log.map(x=>`<div class="log-item">${esc(x)}</div>`).join('');}
function awardBattle(win){const s=load(KEYS.stats,{});s.battles=(s.battles||0)+1;if(win)s.wins=(s.wins||0)+1;save(KEYS.stats,s);awardXP(win?30:5);save(KEYS.battleHistory,[{date:new Date().toISOString(),winner:battleState.winner,...s}].concat(load(KEYS.battleHistory,[])).slice(0,20));}
document.getElementById('clearBattleHistory').onclick=()=>{save(KEYS.battleHistory,[]);document.getElementById('battleLog').innerHTML=''};

function renderBattleHistory(){const root=document.getElementById('battleLog');const history=load(KEYS.battleHistory,[]);if(!root)return;root.innerHTML=history.length?history.slice(0,8).map(h=>`<div class="log-item"><b>${h.winner?esc(cap(h.winner))+' won':'Battle completed'}</b> · ${new Date(h.date).toLocaleString()}</div>`).join(''):'<p class="description">No completed battles yet.</p>'}
/* Mystery */
const mysteryCard=document.getElementById('mysteryCard');let mysteryRevealed=false;
document.getElementById('mysteryBtn').onclick=drawMystery;mysteryCard.onclick=()=>{if(!mysteryRevealed)drawMystery()};async function drawMystery(){const btn=document.getElementById('mysteryBtn');btn.disabled=true;btn.textContent='Opening…';mysteryCard.classList.remove('revealed');try{const id=Math.floor(Math.random()*MAX_POKEMON)+1,p=await getPokemon(id);const sp=await getSpecies(p.id);const rarity=sp.is_mythical?'MYTHICAL':sp.is_legendary?'LEGENDARY':Math.random()<.1?'EPIC':Math.random()<.25?'RARE':Math.random()<.5?'UNCOMMON':'COMMON';const shinyDraw=Math.random()<.03;document.getElementById('mysteryFront').innerHTML=`<div class="mystery-card-inner"><span class="collect-rarity">${rarity}${shinyDraw?' · SHINY':''}</span><img src="${img(p,shinyDraw)}" alt="${p.name}"><h2>${cap(p.name)}</h2><div class="mystery-front-types">${typePills(p)}</div><small>#${String(p.id).padStart(4,'0')} · HP ${stat(p,'hp')}</small></div>`;document.getElementById('mysteryFront').style.setProperty('--mystery-color',typeColor[p.types[0].type.name]);mysteryCard.classList.add('revealed');mysteryRevealed=true;btn.textContent='Draw Another';const history=load(KEYS.mystery,[]);history.unshift({id:p.id,name:p.name,rarity,shiny:shinyDraw});save(KEYS.mystery,history.slice(0,8));document.getElementById('mysteryHistory').innerHTML=history.slice(0,6).map(x=>`<button class="history-item" data-detail="${x.name}"><img src="${x.shiny?img(p,true):official(p)}"><div><b>${cap(x.name)}</b><small>${x.rarity}${x.shiny?' · Shiny':''}</small></div></button>`).join('');document.getElementById('mysteryStats').textContent=`${history.length} discoveries • ${history.filter(x=>x.shiny).length} shiny draws`;awardXP(10)}catch{btn.textContent='Try Again';toast('Mystery draw failed','error')}btn.disabled=false}

/* Quiz */
const quizContent=document.getElementById('quizContent');let quizMode='silhouette';document.querySelectorAll('.quiz-mode').forEach(b=>b.onclick=()=>{quizMode=b.dataset.quizMode;document.querySelectorAll('.quiz-mode').forEach(x=>x.classList.toggle('active',x===b));startQuiz()});async function randomPokemon(){return getPokemon(Math.floor(Math.random()*MAX_POKEMON)+1)}
async function startQuiz(){const score=load(KEYS.stats,{}).quizScore||0;document.getElementById('quizScore').textContent=score;quizContent.innerHTML='<div class="loading-panel">Preparing quiz…</div>';try{const answer=await randomPokemon(),opts=[answer];while(opts.length<4){const p=await randomPokemon();if(!opts.some(x=>x.id===p.id))opts.push(p)}opts.sort(()=>Math.random()-.5);state.quiz={mode:quizMode,answer,opts,answered:false};let content='';if(quizMode==='silhouette')content=`<div class="quiz-card"><p class="eyebrow">SILHOUETTE</p><h2>Who's that Pokémon?</h2><div class="quiz-art"><img class="silhouette" src="${official(answer)}" alt="Mystery silhouette"></div><div class="quiz-options">${opts.map(o=>`<button class="quiz-option" data-quiz-answer="${o.id}">${cap(o.name)}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback"></div></div>`;else if(quizMode==='multiple')content=`<div class="quiz-card"><p class="eyebrow">MULTIPLE CHOICE</p><h2>Which Pokémon is this?</h2><div class="quiz-art"><img src="${official(answer)}" alt="Pokemon"></div><div class="quiz-options">${opts.map(o=>`<button class="quiz-option" data-quiz-answer="${o.id}">${cap(o.name)}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback"></div></div>`;else if(quizMode==='type')content=`<div class="quiz-card"><p class="eyebrow">TYPE QUIZ</p><h2>Which Pokémon has this type?</h2><div class="quiz-art"><div><div class="result-types" style="justify-content:center">${typePills(answer)}</div><p class="quiz-question">Choose the Pokémon that matches these type clues.</p></div></div><div class="quiz-options">${opts.map(o=>`<button class="quiz-option" data-quiz-answer="${o.id}">${cap(o.name)}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback"></div></div>`;else if(quizMode==='stat')content=`<div class="quiz-card"><p class="eyebrow">STAT QUIZ</p><h2>Who has this stat profile?</h2><div class="quiz-art"><div class="bar-list">${bar('HP',stat(answer,'hp'))}${bar('Attack',stat(answer,'attack'))}${bar('Defense',stat(answer,'defense'))}${bar('Speed',stat(answer,'speed'))}</div></div><div class="quiz-options">${opts.map(o=>`<button class="quiz-option" data-quiz-answer="${o.id}">${cap(o.name)}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback"></div></div>`;else{const sp=await getSpecies(answer.id),chain=sp.evolution_chain?await api(sp.evolution_chain.url):null;let family=[];if(chain){const walk=n=>{family.push(pokemonIdFromUrl(n.species.url));n.evolves_to?.forEach(walk)};walk(chain.chain)}const missing=family[Math.floor(Math.random()*family.length)];const m=await getPokemon(missing);const evoOpts=[m];while(evoOpts.length<4){const q=await randomPokemon();if(!evoOpts.some(x=>x.id===q.id))evoOpts.push(q)}content=`<div class="quiz-card"><p class="eyebrow">EVOLUTION QUIZ</p><h2>Which Pokémon belongs in this family?</h2><div class="quiz-art"><p class="quiz-question">${family.length} Pokémon in the evolution family</p></div><div class="quiz-options">${evoOpts.map(o=>`<button class="quiz-option" data-quiz-answer="${o.id}">${cap(o.name)}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback"></div></div>`;state.quiz.answer=m}quizContent.innerHTML=content;document.querySelectorAll('[data-quiz-answer]').forEach(b=>b.onclick=()=>answerQuiz(Number(b.dataset.quizAnswer)))}catch{quizContent.innerHTML='<div class="error-panel"><h2>Quiz unavailable</h2><p>Retry to start another question.</p></div>'}}
function answerQuiz(id){if(state.quiz.answered)return;state.quiz.answered=true;const correct=id===state.quiz.answer.id,fb=document.getElementById('quizFeedback');document.querySelectorAll('[data-quiz-answer]').forEach(b=>{if(Number(b.dataset.quizAnswer)===state.quiz.answer.id)b.classList.add('correct');if(Number(b.dataset.quizAnswer)===id&&!correct)b.classList.add('wrong')});fb.textContent=correct?`Correct! It's ${cap(state.quiz.answer.name)}.`:`Not quite. The answer was ${cap(state.quiz.answer.name)}.`;const s=load(KEYS.stats,{});s.quizScore=(s.quizScore||0)+(correct?10:0);s.quizCorrect=(s.quizCorrect||0)+(correct?1:0);s.quizIncorrect=(s.quizIncorrect||0)+(correct?0:1);s.quizStreak=correct?(s.quizStreak||0)+1:0;s.bestQuizStreak=Math.max(s.bestQuizStreak||0,s.quizStreak);save(KEYS.stats,s);awardXP(correct?15:3);setTimeout(startQuiz,1300)}

/* Cry quiz */
let cryAudio=null;document.getElementById('playCryQuiz').onclick=startCryQuiz;async function startCryQuiz(){const btn=document.getElementById('playCryQuiz');btn.classList.add('playing');try{const answer=await randomPokemon();const opts=[answer];while(opts.length<4){const p=await randomPokemon();if(!opts.some(x=>x.id===p.id))opts.push(p)}opts.sort(()=>Math.random()-.5);state.cry={pokemon:answer,opts,answered:false};document.getElementById('cryOptions').innerHTML=opts.map(p=>`<button class="quiz-option" data-cry-answer="${p.id}">${cap(p.name)}</button>`).join('');document.getElementById('cryPrompt').textContent='Listen and choose the Pokémon.';document.querySelectorAll('[data-cry-answer]').forEach(b=>b.onclick=()=>answerCry(Number(b.dataset.cryAnswer)));if(answer.cries?.latest){cryAudio=new Audio(answer.cries.latest);await cryAudio.play().catch(()=>{})}else document.getElementById('cryPrompt').textContent='This Pokémon has no cry available in the API.'}catch{toast('Cry unavailable','error')}setTimeout(()=>btn.classList.remove('playing'),900)}
function answerCry(id){if(state.cry.answered)return;state.cry.answered=true;const correct=id===state.cry.pokemon.id;const s=load(KEYS.stats,{});s.cryScore=(s.cryScore||0)+(correct?10:0);s.cryStreak=correct?(s.cryStreak||0)+1:0;s.bestCryStreak=Math.max(s.bestCryStreak||0,s.cryStreak);save(KEYS.stats,s);document.getElementById('cryScore').textContent=s.cryScore;document.getElementById('cryStreak').textContent=s.cryStreak;document.getElementById('cryBest').textContent=s.bestCryStreak;document.getElementById('cryPrompt').textContent=correct?`Correct! ${cap(state.cry.pokemon.name)}.`:`The answer was ${cap(state.cry.pokemon.name)}.`;awardXP(correct?15:3);setTimeout(startCryQuiz,1300)}

/* Daily + XP + achievements */
function todayKey(){const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
const dailyPool=[{id:'collect-water',text:'Add a Water-type Pokémon to your collection.',check:()=>load(KEYS.collection,[]).some(x=>cache.get(endpoints.pokemon+x.name)?.types?.some(t=>t.type.name==='water'))},{id:'discover-5',text:'View 5 Pokémon today.',check:()=>load(KEYS.daily,{}).viewCount>=5},{id:'favorite',text:'Favorite a Pokémon.',check:()=>load(KEYS.favorites,[]).length>0},{id:'quiz',text:'Answer a quiz question.',check:()=>load(KEYS.stats,{}).quizCorrect>0},{id:'battle',text:'Complete a battle.',check:()=>load(KEYS.stats,{}).battles>0}];
function daily(){let d=load(KEYS.daily,{});if(d.date!==todayKey()){d={date:todayKey(),challenge:dailyPool[Math.floor(Math.random()*dailyPool.length)].id,done:false,viewCount:0,streak:d.streak||0}}const ch=daily||{};return {d,ch:defChallenge(d.challenge)}}function defChallenge(id){return dailyPool.find(x=>x.id===id)||dailyPool[0]}
function renderDaily(){let d=load(KEYS.daily,{});if(!d.date){d={date:todayKey(),challenge:dailyPool[Math.floor(Math.random()*dailyPool.length)].id,done:false,viewCount:0,streak:0};save(KEYS.daily,d)}const c=defChallenge(d.challenge);const done=d.done||c.check();if(done&&!d.done){d.done=true;d.streak=(d.streak||0)+1;save(KEYS.daily,d);awardXP(25)}document.getElementById('dailyHome').innerHTML=`<div class="mission-card"><strong>${esc(c.text)}</strong><p>${done?'Challenge complete! Come back tomorrow for another mission.':'Complete this today to earn 25 XP.'}</p><div class="mission-progress"><i style="width:${done?'100':'15'}%"></i></div><button class="secondary-btn" data-page-direct="trainer">View Progress</button></div>`}
function awardXP(amount){const s=load(KEYS.stats,{});s.xp=(s.xp||0)+amount;save(KEYS.stats,s);updateLevelUI()}
function levelInfo(xp){const level=Math.floor(xp/100)+1;return{level,xpIn:xp%100,need:100}}
function updateLevelUI(){const s=load(KEYS.stats,{}),l=levelInfo(s.xp||0);document.getElementById('sideLevel').textContent=`Level ${l.level} • ${s.xp||0} XP`;document.getElementById('trainerLevel').textContent=`Level ${l.level}`;document.getElementById('xpText').textContent=`${l.xpIn} / ${l.need} XP`;document.getElementById('xpBar').style.width=l.xpIn+'%';}
const achievements=[['first','FIRST DISCOVERY','Discover a Pokémon.','◉',s=>load(KEYS.recent,[]).length>=1],['collector25','COLLECTOR','Collect 25 Pokémon.','▥',s=>load(KEYS.collection,[]).length>=25],['collector100','SUPER COLLECTOR','Collect 100 Pokémon.','★',s=>load(KEYS.collection,[]).length>=100],['shiny5','SHINY HUNTER','Collect 5 shiny Pokémon.','✧',s=>load(KEYS.shiny,[]).length>=5],['legendary','LEGENDARY TRAINER','Collect a Legendary Pokémon.','♛',s=>{const ids=new Set([144,145,146,150,243,244,245,249,250,377,378,379,380,381,382,383,384,385,386,480,481,482,483,484,485,486,487,488,638,639,640,641,642,643,644,645,646,716,717,718,785,786,787,788,789,790,791,792,800,888,889,890,891,892,894,895,896,897,898,905,1001,1002,1003,1004,1007,1008,1009,1010,1011,1012,1013,1014,1015,1016,1017,1018,1020,1021,1022,1023,1024,1025]);return load(KEYS.collection,[]).some(x=>ids.has(Number(x.id))) }],['battle','BATTLE READY','Complete your first battle.','⚔',s=>(load(KEYS.stats,{}).battles||0)>=1],['battle25','BATTLE MASTER','Complete 25 battles.','⚔',s=>(load(KEYS.stats,{}).battles||0)>=25],['quiz10','QUIZ MASTER','Reach a 10-question correct streak.','✦',s=>(load(KEYS.stats,{}).bestQuizStreak||0)>=10],['evolution25','EVOLUTION MASTER','View 25 recent discoveries.','↗',s=>load(KEYS.recent,[]).length>=10],['regional','REGIONAL EXPERT','Collect 50 Pokémon.','⌖',s=>load(KEYS.collection,[]).length>=50]];
function renderAchievements(){document.getElementById('achievementsGrid').innerHTML=achievements.map(a=>{const ok=typeof a[4]==='function'&&a[4]();return `<div class="achievement ${ok?'unlocked':''}"><div class="badge">${a[3]}</div><b>${a[1]}</b><small>${a[2]}</small></div>`}).join('')}

/* Trainer */
function renderTrainer(){const t=load(KEYS.trainer,{name:'PokéTrainer',avatar:'⚡'}),s=load(KEYS.stats,{}),c=load(KEYS.collection,[]),f=load(KEYS.favorites,[]),sh=load(KEYS.shiny,[]);document.getElementById('trainerNameInput').value=t.name;document.getElementById('trainerAvatarInput').value=t.avatar;document.getElementById('profileAvatar').textContent=t.avatar;document.getElementById('headerTrainerName').textContent=t.name;document.getElementById('headerAvatar').textContent=t.avatar;document.getElementById('trainerStats').innerHTML=[['Collection',c.length],['Favorites',f.length],['Shiny',sh.length],['Battles',s.battles||0],['Wins',s.wins||0],['Quiz Score',s.quizScore||0]].map(x=>`<div><b>${x[1]}</b><span>${x[0]}</span></div>`).join('');updateLevelUI();renderAchievements()}
document.getElementById('saveTrainer').onclick=()=>{const t={name:document.getElementById('trainerNameInput').value.trim()||'PokéTrainer',avatar:document.getElementById('trainerAvatarInput').value};save(KEYS.trainer,t);renderTrainer();toast('Trainer profile saved')};document.getElementById('resetProgress').onclick=()=>{if(!confirm('Reset local trainer progress, collection, teams and scores?'))return;Object.values(KEYS).forEach(k=>localStorage.removeItem(k));state.compare=[];state.team=[];renderTrainer();refreshAllUserViews();toast('Local progress reset')};

/* Favorites / Shiny */
async function idsToPokemon(ids){let out=[];for(let i=0;i<ids.length;i+=20)out.push(...await Promise.all(ids.slice(i,i+20).map(id=>getPokemon(id).catch(()=>null))));return out.filter(Boolean)}
async function renderFavorites(){const root=document.getElementById('favoriteCards'),ids=load(KEYS.favorites,[]);if(!ids.length){root.innerHTML='<div class="empty-state"><div>♡</div><h2>No favorites yet</h2><p>Use the heart on any Pokémon to add it here.</p></div>';return}root.innerHTML=(await idsToPokemon(ids)).map(p=>pokemonCard(p)).join('')}
async function renderShiny(){const root=document.getElementById('shinyCards'),ids=load(KEYS.shiny,[]);document.getElementById('shinyProgress').textContent=`${ids.length} / ${MAX_POKEMON}`;if(!ids.length){root.innerHTML='<div class="empty-state"><div>✧</div><h2>Your shiny collection is empty</h2><p>Search a Pokémon above and mark it as shiny collected.</p></div>';return}const ps=await idsToPokemon(ids);root.innerHTML=ps.map(p=>pokemonCard(p,{collection:true,shiny:true})).join('')}
document.getElementById('shinySearchBtn').onclick=async()=>{const v=document.getElementById('shinySearch').value.trim();if(!v)return;try{const p=await getPokemon(v);document.getElementById('shinySearchResult').innerHTML=`<div class="panel" style="padding:12px;margin-bottom:12px;display:flex;align-items:center;gap:12px"><img src="${img(p,true)}" style="width:80px;height:80px;object-fit:contain"><div style="flex:1"><b>${cap(p.name)}</b><p class="description">Mark this Pokémon as collected shiny.</p></div><button class="primary-btn" data-shiny="${p.id}">${isShiny(p.id)?'✓ Shiny Collected':'✧ Mark Shiny'}</button></div>`}catch{toast('Pokémon not found','error')}};

/* Regions */
const regions=[['Kanto',1,1,151],['Johto',2,152,251],['Hoenn',3,252,386],['Sinnoh',4,387,493],['Unova',5,494,649],['Kalos',6,650,721],['Alola',7,722,809],['Galar',8,810,905],['Paldea',9,906,1025]];
function renderRegions(){const c=load(KEYS.collection,[]);document.getElementById('regionCards').innerHTML=regions.map(r=>{const count=c.filter(x=>x.id>=r[2]&&x.id<=r[3]).length,total=r[3]-r[2]+1;return `<button class="region-card" data-region="${r[1]}"><p>GENERATION ${r[1]}</p><h3>${r[0]}</h3><p>${total} Pokédex species in the main national range</p><div class="region-progress"><i style="width:${Math.min(100,count/total*100)}%"></i></div><small>${count} / ${total} collected</small></button>`}).join('')}
document.addEventListener('click',async e=>{const r=e.target.closest('[data-region]');if(!r)return;const gen=await api(endpoints.generation+r.dataset.region);const root=document.getElementById('regionPokemon');const ids=gen.pokemon_species.map(x=>pokemonIdFromUrl(x.url)).sort((a,b)=>a-b);root.innerHTML=`<h2>${cap(gen.main_region.name)} Pokémon</h2><div class="cards-grid" id="regionCardsInner"></div>`;const inner=document.getElementById('regionCardsInner');for(let i=0;i<Math.min(ids.length,120);i+=20){const ps=await Promise.all(ids.slice(i,i+20).map(getPokemon));inner.insertAdjacentHTML('beforeend',ps.map(p=>pokemonCard(p)).join(''))}});

/* Analytics */
async function renderAnalytics(){const c=load(KEYS.collection,[]),f=load(KEYS.favorites,[]),sh=load(KEYS.shiny,[]),s=load(KEYS.stats,{});document.getElementById('analyticsStats').innerHTML=[['Collected',c.length],['Favorites',f.length],['Shiny',sh.length],['Battles',s.battles||0],['Wins',s.wins||0],['Quiz Score',s.quizScore||0]].map(x=>`<div class="analytics-stat"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');const ps=await idsToPokemon(c.slice(0,200)),counts={};ps.forEach(p=>p.types.forEach(t=>counts[t.type.name]=(counts[t.type.name]||0)+1));document.getElementById('typeChart').innerHTML=TYPES.map(t=>[t,counts[t]||0]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]).map(x=>`<div class="chart-row"><span>${cap(x[0])}</span><div><i style="width:${Math.min(100,x[1]/Math.max(1,c.length)*100)}%"></i></div><b>${x[1]}</b></div>`).join('')||'<p class="description">Collect Pokémon to see analytics.</p>';const genCounts=regions.map(r=>[r[0],c.filter(x=>x.id>=r[2]&&x.id<=r[3]).length]);document.getElementById('generationChart').innerHTML=genCounts.map(x=>`<div class="chart-row"><span>${x[0]}</span><div><i style="width:${Math.min(100,x[1]/Math.max(1,c.length)*100)}%"></i></div><b>${x[1]}</b></div>`).join('')}

/* Home */
async function renderHome(){renderDaily();renderHomeProgress();const recent=load(KEYS.recent,[]);const root=document.getElementById('recentCards');if(!recent.length)root.innerHTML='<p class="description">Your recently viewed Pokémon will appear here.</p>';else{const ps=await idsToPokemon(recent.slice(0,5).map(x=>x.id));root.innerHTML=ps.map(p=>`<button class="recent-card" data-detail="${p.name}"><img src="${official(p)}" alt="${p.name}"><div><b>${cap(p.name)}</b><small>#${p.id}</small></div></button>`).join('')}const day=(new Date().getDate()%MAX_POKEMON)+1;try{const p=await getPokemon(day);document.getElementById('potdName').textContent=cap(p.name);document.getElementById('potdContent').innerHTML=`<img src="${official(p)}" alt="${p.name}"><div class="potd-meta"><div class="result-types">${typePills(p)}</div><h2>${cap(p.name)}</h2><p>#${p.id} · HP ${stat(p,'hp')} · Speed ${stat(p,'speed')}</p><button class="primary-btn" data-detail="${p.name}">View Info</button><button class="secondary-btn" data-add="${p.id}">＋ Add</button></div>`;document.getElementById('potdInfo').onclick=()=>openDetail(p.name)}catch{}}async function renderHomeProgress(){const c=load(KEYS.collection,[]),pct=Math.round(c.length/MAX_POKEMON*100);document.getElementById('homeCollectionPct').textContent=pct+'%';document.getElementById('homeCollectionCount').textContent=`${c.length} / ${MAX_POKEMON}`;document.getElementById('homeProgressBar').style.width=pct+'%';const counts={};if(c.length){const ps=await idsToPokemon(c.slice(0,200).map(x=>x.id));ps.forEach(p=>p.types.forEach(t=>counts[t.type.name]=(counts[t.type.name]||0)+1))}document.getElementById('homeTypeBreakdown').innerHTML=TYPES.map(t=>counts[t]?`<span title="${t}: ${counts[t]}" style="background:${typeColor[t]}"></span>`:'').join('')||'<span style="background:#21405f"></span>'}
document.getElementById('clearRecent').onclick=()=>{save(KEYS.recent,[]);renderHome();toast('Recently viewed cleared')};

/* Theme/settings */
function applyTheme(v){let theme=v;if(v==='system')theme=matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';document.body.classList.toggle('light',theme==='light');document.getElementById('themeQuick').textContent=theme==='light'?'☀':'☾';save(KEYS.theme,v)}
function loadSettingsUI(){document.getElementById('themeSelect').value=load(KEYS.theme,'system');document.getElementById('reducedMotion').checked=load(KEYS.settings,{}).reducedMotion||false;applyTheme(load(KEYS.theme,'system'))}
document.getElementById('themeSelect').onchange=e=>applyTheme(e.target.value);document.getElementById('reducedMotion').onchange=e=>{const s=load(KEYS.settings,{});s.reducedMotion=e.target.checked;save(KEYS.settings,s);document.body.classList.toggle('reduced-motion',e.target.checked)};document.getElementById('themeQuick').onclick=()=>applyTheme(document.body.classList.contains('light')?'dark':'light');

/* Shared action handlers */
document.addEventListener('click',async e=>{const shiny=e.target.closest('[data-shiny]');if(shiny){e.stopPropagation();toggleShiny(shiny.dataset.shiny)}const battleAdd=e.target.closest('[data-battle-add]');if(battleAdd){closeDetail();showPage('battle');document.getElementById('battleOne').value=battleAdd.dataset.battleAdd}const play=e.target.closest('[data-play-cry]');if(play){try{const p=await getPokemon(play.dataset.playCry);if(p.cries?.latest)new Audio(p.cries.latest).play();else toast('No cry is available','error')}catch{}}});
function refreshAllUserViews(){updateLevelUI();renderHomeProgress();if(state.currentPage==='collection')renderCollection();if(state.currentPage==='favorites')renderFavorites();if(state.currentPage==='shiny')renderShiny();if(state.currentPage==='trainer')renderTrainer();if(state.currentPage==='analytics')renderAnalytics();if(state.currentPage==='home')renderHome()}

/* Init */
(function init(){const theme=load(KEYS.theme,'system');applyTheme(theme);const settings=load(KEYS.settings,{});if(settings.reducedMotion)document.body.classList.add('reduced-motion');renderHome();renderCollection();renderTrainer();renderCompare();renderTeam();updateLevelUI();})();
